        match_type,
        active
    )
SELECT
    gm.id,
    sk.keyword,
    sk.normalized_keyword,
    sk.weight,
    sk.match_type,
    sk.active
FROM
    seed_keywords sk
    JOIN group_masters gm ON gm.group_key = sk.group_key;
